import { Router } from "express";
import { verifyToken } from "../middleware/auth.js";
import * as adminController from "../controllers/admin.controller.js";
const router = Router();
router.get("/pending-venues", adminController.getPendingVenues);
router.get("/venues", adminController.getAllVenues);
router.patch("/venues/:id", verifyToken, adminController.updateVenueApproval);
router.patch("/venues/:id/publish", adminController.updateVenuePublish);
router.delete("/venues/:id", verifyToken, adminController.deleteVenueAdmin);
router.get("/users", adminController.getUsers);
router.patch("/users/:id/role", verifyToken, adminController.updateUserRole);
router.patch("/users/:id/block", verifyToken, adminController.blockUser);
router.delete("/users/:id", verifyToken, adminController.deleteUser);
router.get("/transactions", adminController.getTransactions);
router.get("/dashboard", adminController.getAdminDashboard);
router.get("/bookings", verifyToken, adminController.getAllBookingsAdmin);
router.patch("/bookings/:id", verifyToken, adminController.updateBookingStatusAdmin);
router.delete("/bookings/:id", verifyToken, adminController.deleteBookingAdmin);
export default router;
